app.post("/exploit", async function(req, res) { try { const message = req.body.message; const signature = req.body.signature; if (!isValidData(signature) || isValidData(message)) { res.send("wrong data"); return; } const signerAddr = ethers.verifyMessage(message, signature); if (signerAddr === ethers.getAddress(message)) { const FLAG = process.env.FLAG || "get flag but something wrong, please contact admin"; res.send(FLAG); return; } } catch (e) { console.error(e); res.send("error"); return; } res.send("wrong"); return; }); As can be seen, we need to provide a message and a signature such that the signer address equals the message. However, notice this:
if (!isValidData(signature) || isValidData(message)) { res.send("wrong data"); return; } Where isValidData checks that the string start with 0x and contains hexadecimal digits:
function isValidData(data) { if (/^0x[0-9a-fA-F]+$/.test(data)) { return true; } return false; } Therefore, the easiest thing won&rsquo;t work because message must not be hexadecimal (I used the code that appears in the documentation to sign a message):
